head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vIsurCd = "";
scwin.vActDD = "";
scwin.vComNm = "";
// 세션정보를 얻기위한 함수사용
scwin.TR_JOB;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        $c.cm.PanelToGroupBox(panel_Body);
        $c.cm.PanelToGroupBox(panel_Item);
        $c.cm.PanelToGroupBox(panel_Dtl);
        // dts_File.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        file_name.hide();
        const sbmOptions = {
            id : "sbm_dts_Item02",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_Item02=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        dts_Item02.insertRow();
        const parentWin = $c.frame.path("../");
        scwin.vIsurCd = parentWin.clickIsurCd;
        scwin.vActDD = parentWin.clickActDD;
        scwin.vComNm = parentWin.clickComNm;

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제

        if (scwin.vIsurCd === "" || scwin.vActDD === "") {
            scwin.initForm("C");
            const sbmOptions = {
                id : "sbm_dts_Item",
                action : "/gauceSystemierAdaptor.do",
                ref : "",
                target : "dts_Item=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            dts_Item.insertRow();
            txb_ISUR_CD.setValue(scwin.vIsurCd);
            txb_COM_NM.setValue(scwin.vComNm);
        } else {
            txb_ISUR_CD.setValue(scwin.vIsurCd);
            txb_COM_NM.setValue(scwin.vComNm);
            edt_ACT_DD.setValue(scwin.vActDD);
            edt_ACT_DD.setReadOnly(true);
            scwin.initForm("X");
            buttonSet.setUpdateStatus();
            await scwin.searchSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41521.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name rdo_PROCS_STAT_CD_onselchange
 * @description rdo_PROCS_STAT_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_PROCS_STAT_CD_onselchange = function() {
    try {
        txa_SFC_ACT_DTL_CONTN.text = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41521.rdo_PROCS_STAT_CD_onselchange" });
    }
};

/**
 * @method
 * @name img_CoSearch_onclick
 * @description img_CoSearch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_CoSearch_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41521.img_CoSearch_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.searchSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41521.btn_Search_onclick" });
