};

/**
 * @method
 * @name btn_Delete02_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Delete02_onclick = async function() {
    try {
        await scwin.trs02(TR_JOB_DELETE);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41521.btn_Delete02_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41521.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_ACT_DD_onclick
 * @description img_ACT_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ACT_DD_onclick = function() {
    try {
        popUpCalendar2(edt_ACT_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41521.img_ACT_DD_onclick" });
    }
};

/**
 * @method
 * @name dts_DoubleChk_OnLoadError
 * @description dts_DoubleChk 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DoubleChk_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_DoubleChk);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41521.dts_DoubleChk_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Item_OnLoadError
 * @description dts_Item 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Item_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Item);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41521.dts_Item_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Item_OnLoadCompleted
 * @description dts_Item 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Item_OnLoadCompleted = async function(rowcount) {
    try {
        if (rowcount > 0) {
            await scwin.fileReadSync();
            await scwin.dtlSearchSync("1");
            await scwin.dtlSearchSync("2");
            await scwin.dtlSearchSync("3");
            await scwin.dtlSearchSync("4");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41521.dts_Item_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        $c.lc.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41521.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        scwin.initForm("X");
        buttonSet.setUpdateStatus();
        scwin.parentRefresh();
        if (scwin.TR_JOB === "D") {
            await $c.win.closePopup();
        } else {
            await scwin.searchSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41521.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save02_OnFail
 * @description Save02 On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save02_OnFail = async function() {
    try {
        $c.lc.fn_alertMsg('F');
        await $c.win.alert(trs_Save02);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41521.trs_Save02_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save02_OnSuccess
 * @description Save02 On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save02_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        await scwin.dtlSearchSync(rdo_PROCS_STAT_CD.getValue());
        scwin.parentRefresh();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41521.trs_Save02_OnSuccess" });
    }
};

/**
 * @method
 * @name inf_find_OnClick
 * @description inf_find 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.inf_find_OnClick = function() {
    try {
        const filenm = file_name.getValue();
        dts_File.setCellData(dts_File.getRowPosition(), "fileInfo", inf_find.getValue());
        file_name.setValue(inf_find.getValue());
        if (inf_find.getValue() === "") {
            file_name.setValue(filenm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41521.inf_find_OnClick" });
    }
};

/**
 * @method
 * @name btn_lineadd_onclick
 * @description 「파일추가」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_lineadd_onclick = async function() {
    try {
        if (dts_File.getRowCount() === 5) {
            await $c.win.alert("더이상 추가하실 수 없습니다.");
            return;
        }
        dts_File.insertRow();
        inf_find.open();
        if (inf_find.getValue() !== "") {
            dts_File.setCellData(dts_File.getRowPosition(), "fileInfo", inf_find.getValue());
            file_name.setValue(inf_find.getValue());
        } else {
            dts_File.removeRow(dts_File.getRowPosition());
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41521.btn_lineadd_onclick" });
    }
};

/**
 * @method
 * @name btn_linedelete_onclick
 * @description 「파일삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_linedelete_onclick = function() {
    try {
        dts_File.removeRow(dts_File.getRowPosition());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41521.btn_linedelete_onclick" });
    }
};

/**
 * @method
 * @name grd_ATTACH_FILE_OnDblClick
 * @description grd_ATTACH_FILE 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_ATTACH_FILE_OnDblClick = function(row, colid) {
    try {
        if (row === 0) return;
        if (dts_File.getRowStatus(dts_File.getRowPosition()) === 0) {
            scwin.filedown(dts_File);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41521.grd_ATTACH_FILE_OnDblClick" });
    }
};

/**
 * @method
 * @name grd_List01_OnClick
 * @description grd_List01 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List01_OnClick = function(row, colid) {
    try {
        if (row === 0) return;
        scwin.setDataItem02(dts_List01, row);
        rdo_PROCS_STAT_CD.setValue("1");
        txa_SFC_ACT_DTL_CONTN.text = dts_List01.getCellData(row, "SFC_ACT_DTL_CONTN");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41521.grd_List01_OnClick" });
    }
};

/**
 * @method
 * @name grd_List02_OnClick
 * @description grd_List02 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List02_OnClick = function(row, colid) {
    try {
        if (row === 0) return;
        scwin.setDataItem02(dts_List03, row);
        rdo_PROCS_STAT_CD.setValue("3");
        txa_SFC_ACT_DTL_CONTN.text = dts_List03.getCellData(row, "SFC_ACT_DTL_CONTN");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41521.grd_List02_OnClick" });
    }
};

/**
 * @method
 * @name grd_List03_OnClick
 * @description grd_List03 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List03_OnClick = function(row, colid) {
    try {
        if (row === 0) return;
        scwin.setDataItem02(dts_List02, row);
        rdo_PROCS_STAT_CD.setValue("2");
        txa_SFC_ACT_DTL_CONTN.text = dts_List02.getCellData(row, "SFC_ACT_DTL_CONTN");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41521.grd_List03_OnClick" });
    }
};

/**
 * @method
 * @name grd_List04_OnClick
 * @description grd_List04 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List04_OnClick = function(row, colid) {
    try {
        if (row === 0) return;
        scwin.setDataItem02(dts_List04, row);
        rdo_PROCS_STAT_CD.setValue("4");
        txa_SFC_ACT_DTL_CONTN.text = dts_List04.getCellData(row, "SFC_ACT_DTL_CONTN");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41521.grd_List04_OnClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchSync
 * @description 증선위조치결과 정보조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchSync = async function() {
    const pIsurCd = txb_ISUR_CD.getValue();
    const pComNm = txb_COM_NM.getValue();
    const pActDd = edt_ACT_DD.getValue();
    url += "&method=searchSfcActRsltDetail";
    url += "&inputMessageId=SFC_ACT_RSLT_INPUT_OUT";
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&ACT_DD=" + edt_ACT_DD.getValue();
    const sbmOptions = {
        id : "sbm_dts_Item",
        action : "/RepMajagnt.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (txb_ISUR_CD.getValue() === "" || edt_ACT_DD.getValue() === "") {
        await $c.win.alert("[해당회사는 입력 데이터가 없습니다.]");
        dts_Item.insertRow();
        txb_ISUR_CD.setValue(pIsurCd);
        txb_COM_NM.setValue(pComNm);
        edt_ACT_DD.setValue(pActDd);
    }
};

/**
 * @method
 * @name fileReadSync
 * @description file Read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileReadSync = async function() {
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstmgt.sfcactrslt.select.attachfile";
    url += "&{P}param01=" + txb_ISUR_CD.getValue();
    url += "&{P}param02=" + edt_ACT_DD.getValue();
    const sbmOptions = {
        id : "sbm_dts_File",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_File=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name dtlSearchSync
 * @description dtl Search Sync 처리
 * @param {*} gubn gubn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dtlSearchSync = async function(gubn) {
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstmgt.select.sfcactrslt.dtl.contn.condition";
    url += "&{P}param01=" + txb_ISUR_CD.getValue();
    url += "&{P}param02=" + edt_ACT_DD.getValue();
    url += "&{P}param03=" + gubn;
    if (gubn === "1") {
        const sbmOptions = {
            id : "sbm_dts_List01",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_List01=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (gubn === "2") {
        const sbmOptions = {
            id : "sbm_dts_List02",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_List02=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (gubn === "3") {
        const sbmOptions = {
            id : "sbm_dts_List03",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_List03=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (gubn === "4") {
        const sbmOptions = {
            id : "sbm_dts_List04",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_List04=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
    txa_SFC_ACT_DTL_CONTN.text = "";
};

/**
 * @method
 * @name checkDoubleInput
 * @description 신규입력시 중복입력여부를 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkDoubleInput = async function() {
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&ACT_DD=" + edt_ACT_DD.getValue();
    const sbmOptions = {
        id : "sbm_dts_DoubleChk",
        action : "/RepMajagnt.do",
        ref : "",
        target : "dts_DoubleChk=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const str = dts_DoubleChk.getCellData(1, "DBINPUT_YN");
    if (str === 'Y') {
        await $c.win.alert("[해당회사는 이미 동일한 조치일에 입력 데이터가 있습니다.]");
        return false;
    } else if (str === 'N') {
        return true;
    }
};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @param {*} jobType jobType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(jobType) {
    let vScrenTpCD;
    if (scwin.TR_JOB === 'I') {
        vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB === 'U') {
        vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB === 'D') {
        vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    scwin.setDataItem();
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     JOB_TYPE : jobType
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/RepMajagnt.do",
        ref : "dts_Item,dts_File",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name trs02
 * @description trs02 처리
 * @param {*} jobType jobType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs02 = async function(jobType) {
    if (await scwin.checkForm()) {
        if (txa_SFC_ACT_DTL_CONTN.getValue() === "") {
            await $c.win.alert("[내용]을 입력하세요.");
            return false;
        }
        scwin.setDataItem02("", "", jobType);
        trs_Save02.KeyName = "toinb_dataid4";
        // [전환검토] trs_Save02.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     JOB_TYPE : jobType
        // };
        const sbmOptions = {
            id : "sbm_trs_Save02",
            action : "/RepMajagnt.do",
            ref : "dts_Item02",
            target : "trs_Save02=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initForm
 * @description init Form 처리
 * @param {*} initTyp initTyp
 * @returns {void}
 * @hidden N
 */
scwin.initForm = function(initTyp) {
    if (initTyp === "C") {
        img_CoSearch.setBackgroundImage("../img/btn_search.gif");
        img_CoSearch.setDisabled(false);
    } else if (initTyp === "X") {
        img_CoSearch.setBackgroundImage("../img/btn_search_d.gif");
        img_CoSearch.setDisabled(true);
        btn_Search.setBackgroundImage("../img/btn_select_d.gif");
        btn_Search.setDisabled(true);
        img_ACT_DD.src = "../img/icn_calendar_d.gif";
        img_ACT_DD.setDisabled(true);
    }
};

/**
 * @method
 * @name filedown
 * @description filedown 처리
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function(dtsObj) {
    const vIsurCd = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "ISUR_CD");
    const vActDD = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "ACT_DD");
    const attach_seq = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "ATTACH_SEQ");
    location.href = "/filedownload.do?ISUR_CD=" + scwin.vIsurCd + "&ACT_DD=" + scwin.vActDD + "&attach_seq=" + attach_seq + "&gubun=24";
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (edt_ACT_DD.getValue() === "") {
        await $c.win.alert("[조치일]을 입력하세요.");
        return false;
    }
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("[회사코드]를 입력하세요.");
        return false;
    }
    if (txb_AUDTR_NM.getValue() === "") {
        await $c.win.alert("[감사인]을 입력하세요.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name setDataItem
 * @description set Data Item 처리
 * @returns {void}
 * @hidden N
 */
scwin.setDataItem = function() {
    dts_Item.setCellData(1, "ISUR_CD", txb_ISUR_CD.getValue());
    dts_Item.setCellData(1, "ACT_DD", edt_ACT_DD.getValue());
    dts_Item.setCellData(1, "AUDTR_NM", txb_AUDTR_NM.getValue());
    dts_Item.setCellData(1, "REMK", txa_REMK.getValue());
};

/**
 * @method
 * @name setDataItem02
 * @description set Data Item02 처리
 * @param {*} dts dts
 * @param {Object} obj 컴포넌트
 * @param {*} jobType jobType
 * @returns {void}
 * @hidden N
 */
scwin.setDataItem02 = function(dts, obj, jobType) {
    if (jobType === TR_JOB_INSERT) {
        dts_Item02.setCellData(1, "SUB_SEQ", "0");
    } else {
        if (Number(obj) > 0) {
            // 그리드에서 선택시
            dts_Item02.setCellData(1, "SUB_SEQ", dts.getCellData(Number(obj), "SUB_SEQ"));
        }
    }
    dts_Item02.setCellData(1, "ISUR_CD", txb_ISUR_CD.getValue());
    dts_Item02.setCellData(1, "ACT_DD", edt_ACT_DD.getValue());
    dts_Item02.setCellData(1, "SFC_DTL_TP_CD", rdo_PROCS_STAT_CD.getValue());
    dts_Item02.setCellData(1, "SFC_ACT_DTL_CONTN", txa_SFC_ACT_DTL_CONTN.getValue());
    if (jobType === TR_JOB_INSERT) {
        LastJob = '저장';
    } else if (jobType === TR_JOB_UPDATE) {
        LastJob = '수정';
    } else if (jobType === TR_JOB_DELETE) {
        LastJob = '삭제';
    }
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        if ($c.pre_newlisting.fn_checkDoubleInput()) {
            await scwin.trs(TR_JOB_INSERT);
        }
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.TR_JOB = 'U';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        await scwin.trs(TR_JOB_UPDATE);
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    scwin.TR_JOB = 'D';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        await scwin.trs(TR_JOB_DELETE);
    }
};

/**
 * @method
 * @name parentRefresh
 * @description parent Refresh 처리
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    const fr_fn_list_sync = $c.frame.path("../").fn_Search;
    fr_fn_list_sync();
};
